import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class CustomerDAO {

    // Saves a customer and returns a Customer carrying the ID generated by SQL Server
    public Customer addCustomer(String firstName, String address, int phoneNumber) throws SQLException {

        String sql = "INSERT INTO Customers (FirstName, Address_, PhoneNumber) VALUES (?, ?, ?)";

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            statement.setString(1, firstName);
            statement.setString(2, address);
            statement.setString(3, String.valueOf(phoneNumber)); // PhoneNumber column is VARCHAR
            statement.executeUpdate();

            try (ResultSet keys = statement.getGeneratedKeys()) {
                if (keys.next()) {
                    return new Customer(keys.getInt(1), firstName, address, phoneNumber);
                }
            }
        }
        throw new SQLException("Customer was saved but no ID was returned.");
    }

    public Customer findById(int customerID) throws SQLException {

        String sql = "SELECT CustomerID, FirstName, Address_, PhoneNumber FROM Customers WHERE CustomerID = ?";

        try (Connection connection = DBConnection.getConnection();
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setInt(1, customerID);

            try (ResultSet rs = statement.executeQuery()) {
                if (rs.next()) {
                    return mapRow(rs);
                }
            }
        }
        return null; // not found
    }

    public List<Customer> getAllCustomers() throws SQLException {

        List<Customer> list = new ArrayList<>();
        String sql = "SELECT CustomerID, FirstName, Address_, PhoneNumber FROM Customers ORDER BY CustomerID";

        try (Connection connection = DBConnection.getConnection();
             Statement statement = connection.createStatement();
             ResultSet rs = statement.executeQuery(sql)) {

            while (rs.next()) {
                list.add(mapRow(rs));
            }
        }
        return list;
    }

    // Converts one database row into a Customer object
    private Customer mapRow(ResultSet rs) throws SQLException {
        return new Customer(
                rs.getInt("CustomerID"),
                rs.getString("FirstName"),
                rs.getString("Address_"),
                Integer.parseInt(rs.getString("PhoneNumber").trim()));
    }
}